elementwise_div_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_div_kernel(const float* input, const float* output, int size, float factor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = input[idx] / factor;
    }
}

torch::Tensor elementwise_div_cuda(torch::Tensor x, float norm) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_div_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float()>, size, norm);

    return out;
}
"""

